import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Relazione di equivalenza","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/j_teoria-degli-insiemi/jc/jcg.md","filePath":"lezioni/j_teoria-degli-insiemi/jc/jcg.md"}`),a={name:`lezioni/j_teoria-degli-insiemi/jc/jcg.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="relazione-di-equivalenza" tabindex="-1">Relazione di equivalenza <a class="header-anchor" href="#relazione-di-equivalenza" aria-label="Permalink to “Relazione di equivalenza”">​</a></h1><p>Più che le relazioni elementari, viste sinora, sono importanti le relazioni &quot;composte&quot;, cioè le relazioni formate da più relazioni elementari.</p><p>Diciamo che la relazione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi></mrow><annotation encoding="application/x-tex">R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> su <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mo>×</mo><mi>A</mi></mrow><annotation encoding="application/x-tex">A \\times A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> è <strong>di equivalenza</strong> se è contemporaneamente riflessiva, simmetrica e transitiva.</p><blockquote><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>R</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{R}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;color:red;">R</span></span></span></span> è relazione di equivalenza se è <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mtext>riflessiva,\xA0simmetrica,\xA0transitiva</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{\\text{riflessiva, simmetrica, transitiva}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">riflessiva,\xA0simmetrica,\xA0transitiva</span></span></span></span></span></p></blockquote><p>Se su un insieme è possibile individuare una relazione di equivalenza allora è possibile individuare un nuovo insieme: l&#39;<strong>insieme quoziente</strong> che vedremo nelle prossime pagine.</p><ul><li><a href="./jcga.html">Insieme quoziente</a></li><li><a href="./jcgb.html">Generazione dell&#39;insieme <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="double-struck">N</mi></mrow><annotation encoding="application/x-tex">\\mathbb{N}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6889em;"></span><span class="mord mathbb">N</span></span></span></span></a></li></ul><p>Vediamo alcuni esempi sulle relazioni di equivalenza:</p><blockquote><p><strong>Nota:</strong> per le proprietà riflessiva, simmetrica, antisimmetrica e transitiva degli esempi fai riferimento agli esempi corrispondenti delle pagine precedenti.</p></blockquote><p>Considero l&#39;insieme degli abitanti dell&#39;Italia e considero la relazione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mrow><mtext>&quot;abita\xA0nella\xA0stessa\xA0citt</mtext><mover accent="true"><mtext>a</mtext><mo>ˋ</mo></mover><mtext>&quot;</mtext></mrow></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{&quot;abita nella stessa città&quot;}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">&quot;abita\xA0nella\xA0stessa\xA0citt</span><span class="mord katex-accent" style="color:red;"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;">a</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord" style="color:red;">ˋ</span></span></span></span></span></span></span><span class="mord" style="color:red;">&quot;</span></span></span></span></span>. La relazione è di equivalenza: infatti è contemporaneamente riflessiva, simmetrica e transitiva.</p><p>Considero i numeri naturali e considero la relazione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mrow><mtext>&quot;</mtext><mover accent="true"><mtext>e</mtext><mo>ˋ</mo></mover><mtext>\xA0maggiore\xA0od\xA0uguale\xA0a&quot;</mtext></mrow></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{&quot;è maggiore od uguale a&quot;}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">&quot;</span><span class="mord katex-accent" style="color:red;"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;">e</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord" style="color:red;">ˋ</span></span></span></span></span></span></span><span class="mord" style="color:red;">\xA0maggiore\xA0od\xA0uguale\xA0a&quot;</span></span></span></span></span>. La relazione non è di equivalenza: è riflessiva e transitiva, ma non è simmetrica (è antisimmetrica).</p><p>Considero una famiglia e la relazione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mrow><mtext>&quot;</mtext><mover accent="true"><mtext>e</mtext><mo>ˋ</mo></mover><mtext>\xA0fratello\xA0di&quot;</mtext></mrow></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{&quot;è fratello di&quot;}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">&quot;</span><span class="mord katex-accent" style="color:red;"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;">e</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord" style="color:red;">ˋ</span></span></span></span></span></span></span><span class="mord" style="color:red;">\xA0fratello\xA0di&quot;</span></span></span></span></span>. La relazione è di equivalenza: infatti è riflessiva, simmetrica e transitiva.</p><p>Considero una famiglia e la relazione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mrow><mtext>&quot;</mtext><mover accent="true"><mtext>e</mtext><mo>ˋ</mo></mover><mtext>\xA0padre\xA0di&quot;</mtext></mrow></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{&quot;è padre di&quot;}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">&quot;</span><span class="mord katex-accent" style="color:red;"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;">e</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord" style="color:red;">ˋ</span></span></span></span></span></span></span><span class="mord" style="color:red;">\xA0padre\xA0di&quot;</span></span></span></span></span>. La relazione non è di equivalenza: infatti non è riflessiva né simmetrica né transitiva.</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};